targets.expr:
count by (os_id) (
  container_image_node_container_info{exported_namespace=~"$namespace", os_id!=""}
)

count by (value) (
  (
    container_image_node_container_info{exported_namespace=~"$namespace"}
    * on(image_id) group_left(value)
    container_image_node_image_labels{key="dev.chainguard.package.main",value!=""}
  )
  or
  label_replace(
    container_image_node_container_info{exported_namespace=~"$namespace"}
    unless on(image_id)
    container_image_node_image_labels{key="dev.chainguard.package.main",value!=""},
    "value", "<UNKNOWN>", "", ""
  )
)

count by (value) (
  (
    container_image_node_container_info{exported_namespace=~"$namespace"}
    * on(image_id) group_left(value)
    container_image_node_image_labels{key="dev.chainguard.image.title",value!=""}
  )
  or
  label_replace(
    container_image_node_container_info{exported_namespace=~"$namespace"}
    unless on(image_id)
    container_image_node_image_labels{key="dev.chainguard.image.title",value!=""},
    "value", "<UNKNOWN>", "", ""
  )
)

count by (value) (
  (
    container_image_node_container_info{exported_namespace=~"$namespace"}
    * on(image_id) group_left(value)
    container_image_node_image_labels{key="org.opencontainers.image.source"}
  )
  or
  label_replace(
    container_image_node_container_info{exported_namespace=~"$namespace"}
    unless on(image_id)
    container_image_node_image_labels{key="org.opencontainers.image.source"},
    "value", "<UNKNOWN>", "", ""
  )
)

100 * count(
  container_image_node_container_info{exported_namespace=~"$namespace", os_id=~"chainguard|wolfi"}
) by (exported_namespace)
/ count(
  container_image_node_container_info{exported_namespace=~"$namespace"}
) by (exported_namespace)

time() - min(
  (container_image_node_image_created >= 0)
  * on(image_id) group_right
  container_image_node_container_info{exported_namespace=~"$namespace"}
)

topk(10,
  max by (exported_namespace, exported_pod, exported_container, image) (
    time() - (
      (container_image_node_image_created >= 0)
      * on(image_id) group_right
      container_image_node_container_info{exported_namespace=~"$namespace"}
    )
  )
)

max by (exported_namespace) (
  time() - (
    (container_image_node_image_created >= 0)
    * on(image_id) group_right
    container_image_node_container_info{exported_namespace=~"$namespace"}
  )
)

count by (os_id) (
  group by (image_id, os_id) (
    container_image_node_container_info{exported_namespace=~"$namespace", os_id!=""}
  )
)

count by (value) (
    label_replace(
      group by (image_id) (
        container_image_node_container_info{exported_namespace=~"$namespace", os_id=~"chainguard|wolfi"}
      ),
      "value", "Chainguard / Wolfi", "", ""
    )
  or
    label_replace(
      group by (image_id) (
        container_image_node_container_info{exported_namespace=~"$namespace", os_id!~"chainguard|wolfi"}
      ),
      "value", "Non-Chainguard", "", ""
    )
)

group by (image, image_id) (
  container_image_node_container_info{exported_namespace=~"$namespace", os_id!~"wolfi|chainguard"}
)

count by (value) (
